function useMedia(q){var _s=useState(false);var m=_s[0];var setM=_s[1];useEffect(function(){var mq=window.matchMedia(q);var fn=function(e){setM(e.matches);};setM(mq.matches);if(mq.addEventListener){mq.addEventListener("change",fn);}else{mq.addListener(fn);}return function(){if(mq.removeEventListener){mq.removeEventListener("change",fn);}else{mq.removeListener(fn);}};}, [q]);return m;}

/* 덱 저장기 — 선수·라인업·세트덱 설정은 DB 한 줄(user_settings)에 한 덩어리로 들어간다.
   한 동작에서 셋을 연달아 저장하면(투수 자리 옮기기, 시트 가져오기, 되돌리기) 아직 다시 그리기 전이라
   나머지 절반이 옛 state 였고, 요청도 한꺼번에 나가서 옛 내용이 마지막에 DB 에 남을 수 있었다.
   그래서 (1) 저장할 때마다 최신 값을 여기에 바로 적고 그 순간의 한 덩어리를 통째로 보내며
   (2) 이 줄을 읽고 쓰는 요청은 부른 순서대로 하나씩 보낸다.
   앞 요청이 waitMs 안에 끝나지 않으면(네트워크 멈춤) 더 기다리지 않고 다음 요청을 보낸다 */
function makeDeckWriter(waitMs) {
  var latest = {};
  var seen = {};
  var tail = Promise.resolve();
  return {
    /* 다시 그릴 때마다 부른다. state 가 새로 바뀐 칸(불러오기 등)만 최신 값으로 맞춘다 */
    sync: function (state) {
      Object.keys(state).forEach(function (k) {
        if (seen[k] !== state[k]) { seen[k] = state[k]; latest[k] = state[k]; }
      });
    },
    /* 바뀐 칸을 적고, 지금의 한 덩어리를 돌려준다 */
    take: function (part) {
      Object.keys(part).forEach(function (k) { latest[k] = part[k]; });
      return { players: latest.players, lineupMap: latest.lineupMap, sdConfig: latest.sdConfig };
    },
    /* job 을 앞 요청이 끝난 뒤에 실행하고, job 의 결과(실패 포함)를 그대로 돌려준다 */
    queue: function (job) {
      var run = tail.then(function () { return job(); });
      var timer = null;
      var guard = new Promise(function (resolve) { timer = setTimeout(resolve, waitMs); });
      tail = Promise.race([run.then(function () {}, function () {}), guard]).then(function () { clearTimeout(timer); });
      return run;
    }
  };
}

/* 옛 형식 줄(선수·라인업·세트덱 설정이 맨 위, decks 없음)을 덱별 형식으로 바꾼다.
   맨 위 데이터는 주인 덱으로 옮긴다 — 예전 '내 덱'(dk_legacy_) → 줄에 저장된 지금 덱 → fallbackId 순.
   빈 decks 만 붙이면 불러오기(loadDeckData)가 decks 쪽만 봐서 맨 위 데이터가 사라진 것처럼 보인다 */
function toDeckFormat(all, list, fallbackId) {
  if (all && all.decks) return all;
  var src = all || {};
  var out = {};
  Object.keys(src).forEach(function(k) { if (k !== "players" && k !== "lineupMap" && k !== "sdConfig") out[k] = src[k]; });
  out.decks = {};
  out.deckList = src.deckList || [];
  out.deckCurrent = src.deckCurrent || "";
  if (src.players || src.lineupMap || src.sdConfig) {
    var legacy = (list || out.deckList).filter(function(d) { return d && String(d.deckId || "").indexOf("dk_legacy_") === 0; })[0];
    var owner = legacy ? legacy.deckId : (src.deckCurrent || fallbackId || "");
    if (owner) out.decks[owner] = { players: src.players || [], lineupMap: src.lineupMap || {}, sdConfig: src.sdConfig || { liveSetPo: 0 } };
  }
  return out;
}

function useData(userId, sdState, setSdState, curDeckId){
  var _p=useState([]);var players=_p[0];var setPlayers=_p[1];
  var _lm=useState({});var lineupMap=_lm[0];var setLineupMap=_lm[1];
  var _sk=useState(DEFAULT_SKILLS);var skills=_sk[0];var setSkills=_sk[1];
  var _pt=useState([]);var potmList=_pt[0];var setPotmListState=_pt[1];
  var _lo=useState(true);var loading=_lo[0];var setLoading=_lo[1];
  var uidRef=React.useRef(userId);uidRef.current=userId;
  var deckIdRef=React.useRef(curDeckId);deckIdRef.current=curDeckId;
  /* 덱 저장기 (makeDeckWriter) — 저장할 최신 값과 요청 순서를 붙잡는다 */
  var writerRef=React.useRef(null);
  if(!writerRef.current)writerRef.current=makeDeckWriter(10000);
  var writer=writerRef.current;
  writer.sync({players:players,lineupMap:lineupMap,sdConfig:sdState});

  /* ── 전체 sd_state 메모리 캐시 (읽기 중복 제거) ── */
  var allDataRef=React.useRef(null);
  var globalLoadedRef=React.useRef(false); /* 선수도감/스킬 1회만 로드 */

  var loadDeckData = async function(uid, deckId) {
    var all = await loadUserData(uid);
    if (!all) return null;
    allDataRef.current = all;
    if (!all.decks) {
      return { players: all.players||[], lineupMap: all.lineupMap||{}, sdConfig: all.sdConfig||{liveSetPo:0} };
    }
    return all.decks[deckId] || null;
  };

  /* 저장: 캐시 사용 → 쓰기 1번만 */
  var saveAllData = async function(uid, deckId, deckData) {
    if (!supabase || !uid || !deckId) return;
    var all = allDataRef.current;
    if (!all) {
      all = await loadUserData(uid) || {};
      allDataRef.current = all;
    }
    if (!all.decks) {
      all = toDeckFormat(all, await sGet("deck-list"), deckId);
      allDataRef.current = all;
    }
    /* deckList/deckCurrent는 localStorage(saveDecks가 항상 최신으로 유지)에서 읽어 보존
       이렇게 해야 saveDecks와의 race condition 방지 */
    var latestList = await sGet("deck-list");
    var latestCur  = await sGet("deck-current");
    if (latestList && latestList.length > 0) all.deckList = latestList;
    if (latestCur) all.deckCurrent = latestCur;
    all.decks[deckId] = deckData;
    allDataRef.current = all;
    await saveUserData(uid, all);
  };

  useEffect(function(){
    if(!userId || !curDeckId) return;
    setLoading(true);
    (async function(){
      if(supabase){
        /* 아직 가는 중인 저장이 끝난 뒤에 읽는다 — 덱을 바꾸자마자 읽으면 방금 저장한 내용이 빠진다 */
        var dd = await writer.queue(function(){ return loadDeckData(userId, curDeckId); });
        if(dd && dd.players && dd.players.length > 0){
          setPlayers(dd.players); setLineupMap(dd.lineupMap||{}); setSdState(dd.sdConfig||{liveSetPo:0});
        } else {
          setPlayers([]); setLineupMap({}); setSdState({liveSetPo:0});
        }
        /* 선수도감/스킬: 로그인 후 딱 1번만 로드 */
        if(!globalLoadedRef.current){
          globalLoadedRef.current = true;
          var gsk=await loadGlobalSkills();
          var rsk=resolveSkills(gsk);
          setSkills(rsk);SKILL_DATA=rsk;LIVE_WEIGHTS=rsk.weights||DEFAULT_WEIGHTS;
          var gpl=await loadGlobalPlayers();
          if(gpl&&gpl.length>0){SEED_PLAYERS.length=0;gpl.forEach(function(p){SEED_PLAYERS.push(p);});}
          /* POTM 전역 명단 로드 - 모든 유저에게 동일 적용 */
          var gpotm=await loadGlobalPotmList();
          GLOBAL_POTM_LIST = Array.isArray(gpotm) ? gpotm : [];
          setPotmListState(GLOBAL_POTM_LIST);
        }
      } else {
        var ver=await sGet(SK.version);var needReset=(!ver||ver<DATA_VERSION);
        if(needReset){await sSet(SK.version,DATA_VERSION);}
        var p2=await sGet("deck-players-"+curDeckId);
        if(!needReset&&p2&&p2.length>0){setPlayers(p2);}else{setPlayers([]);await sSet("deck-players-"+curDeckId,[]);}
        var lm2=await sGet("deck-lineup-"+curDeckId);
        if(!needReset&&lm2&&Object.keys(lm2).length>0){setLineupMap(lm2);}else{setLineupMap({});await sSet("deck-lineup-"+curDeckId,{});}
        if(!globalLoadedRef.current){
          globalLoadedRef.current = true;
          var sk2=await sGet(SK.skills);
          /* 스킬표 버전이 낡았으면 선수 데이터는 두고 스킬표만 새로 받는다 */
          var rsk2=needReset?DEFAULT_SKILLS:resolveSkills(sk2);
          setSkills(rsk2);SKILL_DATA=rsk2;LIVE_WEIGHTS=rsk2.weights||DEFAULT_WEIGHTS;
          if(rsk2!==sk2){await sSet(SK.skills,rsk2);await sSet(SK.skillVersion,SKILL_DATA_VERSION);}
          /* POTM: 로컬 모드에서는 localStorage에 저장 */
          var lpotm=await sGet("global-potm-list");
          GLOBAL_POTM_LIST = Array.isArray(lpotm) ? lpotm : [];
          setPotmListState(GLOBAL_POTM_LIST);
        }
        var sdc=await sGet("deck-sdconfig-"+curDeckId);
        if(!needReset&&sdc){setSdState(sdc);}else{setSdState({liveSetPo:0});}
      }
      setLoading(false);
    })();
  },[userId, curDeckId]);

  SKILL_DATA=skills;if(skills.weights)LIVE_WEIGHTS=skills.weights;

  /* 선수·라인업·세트덱 저장은 나머지 칸도 저장기의 최신 값으로 채워 한 덩어리로 보낸다 */
  var saveP=useCallback(async function(d){
    /* 자동 레벨은 계산값으로, 스킬 이름은 표 이름으로 정리해서 저장한다 (normPlayerSkills) */
    d=normPlayerList(d);
    setPlayers(d);
    var deck=writer.take({players:d});
    var did=deckIdRef.current; var uid=uidRef.current;
    if(supabase&&uid&&did){await writer.queue(function(){ return saveAllData(uid,did,deck); });}
    else if(did){await sSet("deck-players-"+did,d);}
  },[]);

  var saveLM=useCallback(async function(d){
    setLineupMap(d);
    var deck=writer.take({lineupMap:d});
    var did=deckIdRef.current; var uid=uidRef.current;
    if(supabase&&uid&&did){await writer.queue(function(){ return saveAllData(uid,did,deck); });}
    else if(did){await sSet("deck-lineup-"+did,d);}
  },[]);

  var saveSK=useCallback(async function(d){
    setSkills(d);SKILL_DATA=d;
    if(supabase){await saveGlobalSkills(d);}
    else{await sSet(SK.skills,d);}
  },[]);

  var saveSdState=useCallback(async function(nsd){
    var deck=writer.take({sdConfig:nsd});
    var did=deckIdRef.current; var uid=uidRef.current;
    if(supabase&&uid&&did){await writer.queue(function(){ return saveAllData(uid,did,deck); });}
    else if(did){await sSet("deck-sdconfig-"+did,nsd);}
  },[]);

  var savePotmList=useCallback(async function(arr){
    var list = Array.isArray(arr) ? arr : [];
    GLOBAL_POTM_LIST = list;
    setPotmListState(list);
    try {
      if(supabase){
        var ok = await saveGlobalPotmList(list);
        if(ok===false){
          console.error("[POTM] saveGlobalPotmList 반환값 false - DB 저장 실패 가능성. window._SUPABASE.saveGlobalPotmList 등록 여부 확인 필요");
          alert("POTM 저장에 실패했습니다. 브라우저 콘솔(F12)에서 오류를 확인해주세요.");
        } else {
          console.log("[POTM] 저장 성공, "+list.length+"명");
        }
      } else {
        await sSet("global-potm-list", list);
        console.log("[POTM] localStorage 저장, "+list.length+"명");
      }
    } catch(e) {
      console.error("[POTM] savePotmList 예외:", e);
      alert("POTM 저장 중 오류가 발생했습니다: "+(e.message||e));
    }
  },[]);

  return{players:players,lineupMap:lineupMap,skills:skills,potmList:potmList,loading:loading,savePlayers:saveP,saveLineupMap:saveLM,saveSkills:saveSK,saveSdState:saveSdState,savePotmList:savePotmList,allDataRef:allDataRef,queueWrite:writer.queue};
}

