var RS_OPTS = ["0","1","2","3","4","5","6"];

function PosTrainRow(rp) {
  var pos = rp.pos; var pt = POS_TRAIN[pos]; var d = rp.d; var upd = rp.upd; var colors = rp.colors; var stats = rp.stats; var idx = rp.idx;
  var slots = rp.slots || 6;
  var ptSkills = rp.ptSkills || [];
  var _op = useState(false); var skOpen = _op[0]; var setSkOpen = _op[1];
  var chosen = ptSkills.filter(function(x){ return !!x; }).length;
  var mx = pt.mx;
  var lvOpts = []; for (var _i = 0; _i <= mx; _i++) lvOpts.push(String(_i));
  var lv = Math.min(d.level, mx);
  var narrow = rp.mobile;
  var colTpl = (narrow ? "54px 44px " : "70px 56px ") + stats.map(function() { return "minmax(74px,1fr)"; }).join(" ");
  /* 좁은 화면에서는 카드가 가로로 스크롤된다 — 헤더와 열 폭을 맞추려면 여기도 같은 최소폭 */
  return (
    <div style={{ display: "grid", gridTemplateColumns: colTpl, gap: 6, padding: "6px 14px", alignItems: "center", background: idx % 2 === 0 ? "var(--re)" : "transparent", borderBottom: "1px solid var(--bd)", minWidth: "max-content" }}>
      <div style={{ fontWeight: 700, color: "var(--t1)", fontSize: 13 }}>{pos}</div>
      <div style={{ textAlign: "center" }}>
        <select value={String(lv)} onChange={function(e) { upd(pos, "level", parseInt(e.target.value)); }} style={{ width: 50, padding: "4px 2px", textAlign: "center", background: "#1e293b", border: "1px solid #334155", borderRadius: 4, color: "#e2e8f0", fontSize: 14, fontFamily: "var(--m)", fontWeight: 700, outline: "none", cursor: "pointer" }}>
          {lvOpts.map(function(v) { return (<option key={v} value={v}>{v}</option>); })}
        </select>
        <div style={{ fontSize: 7, color: "var(--td)", marginTop: 1 }}>{"/" + mx}</div>
      </div>
      {stats.map(function(stat, i) {
        var arr = pt[stat] || [];
        var base = lv < arr.length ? arr[lv] : (arr[arr.length - 1] || 0);
        var reset = d["r" + i] || 0;
        return (
          <div key={stat} style={{ display: "flex", alignItems: "center", gap: 3, justifyContent: "center" }}>
            <span style={{ fontSize: 12, color: colors[i], fontFamily: "var(--m)", fontWeight: 800 }}>{base}</span>
            <span style={{ fontSize: 11, color: "var(--td)" }}>{"+"}</span>
            <select value={String(reset)} onChange={function(e) { upd(pos, "r" + i, parseInt(e.target.value)); }} style={{ width: 34, padding: "4px 1px", textAlign: "center", background: "#1e293b", border: "1px solid " + colors[i] + "88", borderRadius: 4, color: colors[i], fontSize: 13, fontFamily: "var(--m)", fontWeight: 700, outline: "none", cursor: "pointer" }}>
              {RS_OPTS.map(function(v) { return (<option key={v} value={v}>{v}</option>); })}
            </select>
            <span style={{ fontSize: 11, color: "var(--td)" }}>{"="}</span>
            <span style={{ fontSize: 13, color: colors[i], fontFamily: "var(--m)", fontWeight: 800 }}>{base + reset}</span>
          </div>
        );
      })}
      <button onClick={function(){ setSkOpen(!skOpen); }}
        style={{ gridColumn: "1 / -1", justifySelf: "start", marginTop: 4, padding: "3px 8px", fontSize: 11, fontWeight: 700,
          background: chosen ? "rgba(255,167,38,0.10)" : "transparent", border: "1px solid " + (chosen ? "#FFA72655" : "var(--bd)"),
          borderRadius: 4, color: chosen ? "#FFA726" : "var(--td)", cursor: "pointer" }}>
        {(skOpen ? "▼ " : "▶ ") + "스킬 보너스 " + chosen + "/" + slots}
      </button>
      {skOpen && (
        <div style={{ gridColumn: "1 / -1", display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(150px, 1fr))", gap: 6, padding: "8px 0 4px" }}>
          {Array.from({ length: slots }).map(function(_, si) {
            return (
              <div key={si} style={{ display: "flex", alignItems: "center", gap: 4 }}>
                <span style={{ fontSize: 10, color: "var(--td)", width: 12, textAlign: "right" }}>{si + 1}</span>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <SkillPicker value={ptSkills[si] || ""} options={rp.skillOptions || []} majorOptions={rp.majorOptions || []}
                    width="100%" fontSize={11}
                    onChange={function(v){ rp.updSkill(pos, si, v); }} />
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

function PosTrainPage(p) {
  var mob = p.mobile;
  var sdState = p.sdState || {};
  var setSdState = p.setSdState;
  var groups = [
    { label: "타자", cat: "타자", poss: ["C","1B","2B","3B","SS","LF","CF","RF","DH"], stats: ["파워","정확","선구","인내"], colors: ["#EF5350","#42A5F5","#66BB6A","#FFA726"] },
    { label: "선발", cat: "선발", poss: ["SP1","SP2","SP3","SP4","SP5"], stats: ["변화","구위"], colors: ["#AB47BC","#FF7043"] },
    { label: "중계", cat: "중계", poss: ["RP1","RP2","RP3","RP4","RP5","RP6"], stats: ["변화","구위"], colors: ["#AB47BC","#FF7043"] },
    { label: "마무리", cat: "마무리", poss: ["CP"], stats: ["변화","구위"], colors: ["#AB47BC","#FF7043"] },
  ];
  /* Init posTrain in sdState if missing */
  var ptKey = function(pos) { return "pt_" + pos; };
  var getPT = function(pos) {
    var d = sdState[ptKey(pos)];
    if (d) return d;
    return { level: POS_TRAIN[pos].mx, r0: 0, r1: 0, r2: 0, r3: 0 };
  };
  var upd = function(pos, field, val) {
    setSdState(function(prev) {
      var c = Object.assign({}, prev);
      var cur = Object.assign({}, getPT(pos));
      cur[field] = typeof val === "number" ? val : 0;
      c[ptKey(pos)] = cur;
      return c;
    });
  };

  /* 포지션별 스킬 보너스 — 포지션당 6개까지. 지정된 스킬은 레벨 +1 로 계산된다. */
  var PT_SKILL_SLOTS = 6;
  var skills = p.skills || {};
  var ptsKey = function(pos) { return "pts_" + pos; };
  var getPTS = function(pos) {
    var a = sdState[ptsKey(pos)];
    return Array.isArray(a) ? a.slice(0, PT_SKILL_SLOTS) : [];
  };
  var updSkill = function(pos, idx, val) {
    setSdState(function(prev) {
      var c = Object.assign({}, prev);
      var cur = (Array.isArray(prev[ptsKey(pos)]) ? prev[ptsKey(pos)].slice(0, PT_SKILL_SLOTS) : []);
      while (cur.length < PT_SKILL_SLOTS) cur.push("");
      cur[idx] = val || "";
      c[ptsKey(pos)] = cur;
      return c;
    });
  };

  return (
    <div style={{ padding: mob ? 12 : 18, maxWidth: 900, paddingBottom: mob ? 80 : 18 }}>
      <h2 style={{ fontSize: mob ? 16 : 18, fontWeight: 900, fontFamily: "var(--h)", letterSpacing: 2, color: "var(--t1)", margin: "0 0 4px" }}>{"포지션 특훈"}</h2>
      <p style={{ fontSize: 12, color: "var(--td)", margin: "0 0 12px" }}>{"계정 귀속 - 포지션별 레벨과 재설정 효과를 입력하세요. 스킬 보너스는 포지션당 6개까지 지정할 수 있고, 지정한 스킬은 레벨이 1 올라간 것으로 계산됩니다."}</p>
      {groups.map(function(grp) {
        return (
          <div key={grp.label} style={{ background: "var(--card)", borderRadius: 12, border: "1px solid var(--bd)", overflow: "hidden", marginBottom: 14 }}>
            <div style={{ padding: "8px 14px", borderBottom: "1px solid var(--bd)", background: "rgba(255,213,79,0.02)" }}>
              <span style={{ fontSize: 14, fontWeight: 800, color: "var(--t1)", fontFamily: "var(--h)", letterSpacing: 1 }}>{grp.label}</span>
            </div>
            <div style={{ overflowX: "auto" }}>
            <div style={{ display: "grid", gridTemplateColumns: (mob ? "54px 44px " : "70px 56px ") + grp.stats.map(function() { return "minmax(74px,1fr)"; }).join(" "), gap: 6, padding: "6px 14px", borderBottom: "1px solid var(--bd)", fontSize: 11, fontWeight: 700, color: "var(--td)", minWidth: "max-content" }}>
              <div>{"포지션"}</div>
              <div style={{ textAlign: "center" }}>{"레벨"}</div>
              {grp.stats.map(function(s, i) { return (<div key={s} style={{ textAlign: "center", color: grp.colors[i], whiteSpace: "nowrap" }}>{s + (mob ? "" : " (기본+재설정)")}</div>); })}
            </div>
            {grp.poss.map(function(pos, idx) {
              var catSk = skills[grp.cat] || {};
              return (<PosTrainRow key={pos} pos={pos} d={getPT(pos)} upd={upd} colors={grp.colors} stats={grp.stats} idx={idx} mobile={mob}
                        ptSkills={getPTS(pos)} updSkill={updSkill} slots={PT_SKILL_SLOTS}
                        skillOptions={Object.keys(catSk).filter(function(n){ return skillPickable(n, grp.cat) && !isNatOnlySkill(n, grp.cat); })}
                        majorOptions={Object.keys((skills._major && skills._major[grp.cat]) || {})} />);
            })}
            </div>
          </div>
        );
      })}
    </div>
  );
}

