            {/* Training */}
            <div style={{ fontSize: 14, fontFamily: "var(--m)" }}>
              {isBat ? (
                <React.Fragment><span style={{ color: "#EF5350" }}>{"+" + (pl.trainP||0)}</span>{" "}<span style={{ color: "#42A5F5" }}>{"+" + (pl.trainA||0)}</span>{" "}<span style={{ color: "#66BB6A" }}>{"+" + (pl.trainE||0)}</span>{" "}<span style={{ color: "#FFA726" }}>{"+" + (pl.trainN||0)}</span></React.Fragment>
              ) : (
                <React.Fragment><span style={{ color: "#AB47BC" }}>{"+" + (pl.trainC||0)}</span>{" "}<span style={{ color: "#FF7043" }}>{"+" + (pl.trainS||0)}</span></React.Fragment>
              )}
            </div>
            {/* Spec */}
            <div style={{ fontSize: 14, fontFamily: "var(--m)", color: "var(--t2)" }}>
              {isBat ? ((pl.specPower||0) + "/" + (pl.specAccuracy||0) + "/" + (pl.specEye||0) + "/" + (pl.specPatience||0)) : ((pl.specChange||0) + "/" + (pl.specStuff||0))}
            </div>
