            <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
              {!pl.skill1 && (<span style={{ fontSize: 11, color: "var(--td)" }}>{"-"}</span>)}
              {[1,2,3].map(function(k){
                var nm = pl["skill" + k]; if(!nm) return null;
                var lv = effSkillLv(nm, pl["s"+k+"Lv"], isLvManual(pl), pl.cardType, k, getSkillCat(pl), ptSkillsFor(pl));
                var nb = natSkillMismatch(nm, getSkillCat(pl), pl.cardType) ? "국가대표 전용 스킬입니다. 지금 카드 종류에는 붙을 수 없으니 확인해 주세요" : "";
                return (<SkBadge key={k} name={nm} lv={lv} note={nb} />);
              })}
            </div>
            {/* Potential */}
            <div style={{ fontSize: 14, color: "var(--td)", textAlign: "center" }}>{(pl.pot1 || "-") + "/" + (pl.pot2 || "-")}</div>
